/** A product. */
export type Product = {
  /** The ID of the object. */
  id: string;
  /** Creation timestamp of the object. */
  created_at: string;
  /** Last modification timestamp of the object. */
  modified_at: string | null;
  /** The interval unit for the trial period. */
  trial_interval: TrialInterval | null;
  /** The number of interval units for the trial period. */
  trial_interval_count: number | null;
  /** The name of the product. */
  name: string;
  /** The description of the product. */
  description: string | null;
  /** The visibility of the product. */
  visibility: ProductVisibility;
  /** The recurring interval of the product. If `None`, the product is a one-time purchase. */
  recurring_interval: RecurringInterval | null;
  /** Number of interval units of the subscription. If this is set to 1 the charge will happen every interval (e.g. every month), if set to 2 it will be every other month, and so on. None for one-time products. */
  recurring_interval_count: number | null;
  /** The meter cycle of the product, independent of the billing interval. If `None`, metered concerns follow the billing interval. */
  meter_interval: RecurringInterval | null;
  /** Number of meter interval units. None when no meter cycle is set. */
  meter_interval_count: number | null;
  /** Whether the product is a subscription. */
  is_recurring: boolean;
  /** Whether the product is archived and no longer available. */
  is_archived: boolean;
  /** The ID of the organization owning the product. */
  organization_id: string;
  metadata: MetadataOutputType;
  /** Whether the product can be permanently deleted. Products referenced by an order, subscription, trial or discount cannot be deleted. */
  is_deletable: boolean;
  /** List of prices for this product. */
  prices: Array<LegacyRecurringProductPrice | ProductPrice>;
  /** List of benefits granted by the product. */
  benefits: Array<Benefit>;
  /** List of medias associated to the product. */
  medias: Array<ProductMediaFileRead>;
  /** List of custom fields attached to the product. */
  attached_custom_fields: Array<AttachedCustomField>;
};

/** File to be used as a product media file. */
export type ProductMediaFileRead = {
  /** The ID of the object. */
  id: string;
  organization_id: string;
  name: string;
  path: string;
  mime_type: string;
  size: number;
  storage_version: string | null;
  checksum_etag: string | null;
  checksum_sha256_base64: string | null;
  checksum_sha256_hex: string | null;
  last_modified_at: string | null;
  version: string | null;
  service: "product_media";
  is_uploaded: boolean;
  created_at: string;
  size_readable: string;
  public_url: string;
};

export type ProductPrice = ProductPriceFixed | ProductPriceCustom | ProductPriceSeatBased | ProductPriceUnitBased | ProductPriceMeteredUnit | ProductPriceMeteredTiers;

