export type SubscriptionUpdate = SubscriptionUpdateBase | SubscriptionUpdateSeats | SubscriptionUpdateUnits | SubscriptionUpdateBillingPeriod | SubscriptionCancel | SubscriptionRevoke | SubscriptionPause | SubscriptionResume | SubscriptionUpdateClear;

export type SubscriptionUpdateBase = {
  /**
   * Key-value object allowing you to store additional information.
   *
   * The key must be a string with a maximum length of **40 characters**.
   * The value must be either:
   *
   * * A string with a maximum length of **500 characters**
   * * An integer
   * * A floating-point number
   * * A boolean
   *
   * You can store up to **50 key-value pairs**.
   */
  metadata?: Record<string, string | number | boolean>;
  /** Update subscription to another product. */
  product_id?: string | null;
  /** Determine how to handle the proration billing. If not provided, will use the default organization setting. */
  proration_behavior?: SubscriptionProrationBehavior | null;
  /** Update the subscription to apply a new discount. If set to `null`, the discount will be removed. The change will be applied on the next billing cycle. */
  discount_id?: string | null;
  /** Set or extend the trial period of the subscription. If set to `now`, the trial will end immediately and the first billing cycle will be charged synchronously. The subscription remains trialing if the payment fails. */
  trial_end?: string | "now" | null;
};

export type SubscriptionUpdateBillingPeriod = {
  /**
   * Set a new date for the end of the current billing period. The subscription will renew on this date. The new date can be earlier or later than the current period end, as long as it's in the future.
   *
   * If the subscription is set to cancel at the end of the period, it'll end on this new date instead.
   *
   * It is not possible to update the current billing period on a subscription that's already revoked or not active.
   */
  current_billing_period_end: string;
};

export type SubscriptionUpdateClear = {
  /** Clear the pending subscription update. Set to null to remove scheduled changes. */
  pending_update: null;
};

export type SubscriptionUpdateSeats = {
  /** Update the number of seats for this subscription. */
  seats: number;
  /** Determine how to handle the proration billing. If not provided, will use the default organization setting. */
  proration_behavior?: SubscriptionProrationBehavior | null;
};

export type SubscriptionUpdateUnits = {
  /** Update the number of units for this subscription. */
  units: number;
  /** Determine how to handle the proration billing. If not provided, will use the default organization setting. */
  proration_behavior?: SubscriptionProrationBehavior | null;
};

export type TaxBehavior = "inclusive" | "exclusive";

export type TaxBehaviorOption = "location" | "inclusive" | "exclusive";

/**
 * A per-unit rate up to and including `bound`.
 *
 * Each tier starts where the previous one ended. The first starts at
 * zero. `bound` is None on the last tier if it's unbounded. Rates are
 * in cents and may be fractional.
 *
 * Rates carry no precision bound: this schema reads stored rows, and a
 * bound tightened later would stop them loading. `TierInput` holds the
 * rules new rates must meet.
 */
export type Tier = {
  bound?: number | null;
  unit_amount: string;
};

/**
 * A tier submitted through the API. Rates stop at the reach of the
 * BigInteger amount columns, with 12 decimal places.
 */
export type TierInput = {
  bound?: number | null;
  unit_amount: number | string;
};

export type TierType = "volume" | "graduated";

/**
 * The structure of the shared tiers JSONB column, used by every tiered
 * price type. Purchasable quantity bounds live in the `minimum_units` and
 * `maximum_units` columns, not here.
 */
export type Tiers = {
  type: TierType;
  tiers: Array<Tier>;
};

/**
 * Tiers submitted through the API. Kept apart from `Tiers` so tightening
 * a rule here never stops a stored row from loading.
 */
export type TiersInput = {
  type: TierType;
  tiers: Array<TierInput>;
};

export type TrialInterval = "day" | "week" | "month" | "year";

export type UniqueAggregation = {
  func?: "unique";
  property: string;
};

